  const config = {
    // Foundry distances are scene distance units. Scale the authored values so
    // surviving fixtures illuminate a useful portion of these cramped rooms.
    dim: dim * 1.6,
    bright: bright * 2,
    angle: 360,
    color,
    alpha: Math.max(alpha, 0.48),
    attenuation: 0.45,
    luminosity: 0.72,
    saturation: 0,
    contrast: 0.05,
